  var copied=json.convertValue(next.path("definition"),EbrCommands.Definition.class);var forms=new ArrayList<EbrCommands.Form>(copied.forms());var original=forms.getFirst();var fields=new ArrayList<EbrCommands.Field>(original.fields());var f=fields.getFirst();fields.set(0,new EbrCommands.Field(f.fieldCode(),f.groupCode(),"Changed next-version label",f.fieldType(),f.sourceType(),f.dataType(),f.unitId(),f.precisionScale(),f.requiredFlag(),f.readonlyFlag(),f.defaultExpr(),f.placeholder(),f.helpText(),f.sequenceNo(),f.validationJson(),f.options()));forms.set(0,new EbrCommands.Form(original.formCode(),original.formName(),original.operationDefId(),original.schemaVersion(),original.sequenceNo(),fields));
