  next=templates.command(id(next),"SUBMIT",new EbrCommands.Command(next.path("versionNo").asLong(),"Submit next version"),token(next),key());asRuntime(approver);next=templates.command(id(next),"APPROVE",new EbrCommands.Command(next.path("versionNo").asLong(),"Independent next approval"),token(next),key());next=templates.command(id(next),"PUBLISH",new EbrCommands.Command(next.path("versionNo").asLong(),"Publish next version"),token(next),key());asRuntime(author);
  assertThat(next.path("contentHash").asText()).isNotEqualTo(hash);assertThat(runtime.render(formId)).isEqualTo(before);assertThat(jdbc.queryForObject("SELECT definition_hash FROM ebr_batch_snapshot WHERE main_batch_id=(SELECT main_batch_id FROM prd_execution_unit WHERE id=?)",String.class,executionId)).isEqualTo(hash);
