 @Test void emptyRequiredMultiChoiceRowBlocksSubmitAndActualCompletion(){
  repeating=true;multiChoice=true;initialized(false);save(dependentId,"B","Observed",null,0);submit(dependentId,1);
  runtime.command("SAVE",formId,new EbrRuntimeCommands.Save(0L,"Both actual rows",List.of(new EbrRuntimeCommands.Value("A","ROWS[0]",json.createArrayNode().add("YES"),null,null),new EbrRuntimeCommands.Value("A","ROWS[1]",json.createArrayNode(),null,null))),"\"0\"",key());
  rejectedCode("EBR_RULE_BLOCKED",()->submit(formId,1));assertThat(runtime.evaluateOperation(1,Long.parseLong(operationId)).complete()).isFalse();var op=executionService.operation(1,Long.parseLong(operationId));rejectedCode("EBR_OPERATION_INCOMPLETE",()->executionService.complete(operationId,body("reason","Empty row cannot complete"),token(op),key()));
  runtime.command("SAVE",formId,new EbrRuntimeCommands.Save(1L,"Complete second required row",List.of(new EbrRuntimeCommands.Value("A","ROWS[1]",json.createArrayNode().add("YES"),null,null))),"\"1\"",key());submit(formId,2);assertThat(runtime.evaluateOperation(1,Long.parseLong(operationId)).complete()).isTrue();
 }
